import { describe, test, expect, vi, beforeEach } from 'vitest';
import { renderHook } from '@testing-library/react';
import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
import { useCountryConfig } from './useCountryConfig';
import { COUNTRIES } from '../config/countries';

vi.mock('@salesforce/retail-react-app/app/hooks/use-multi-site', () => ({
  default: vi.fn(),
}));

const mockUseMultiSite = vi.mocked(useMultiSite);

function mockSite(siteId: string, localeId: string): void {
  mockUseMultiSite.mockReturnValue({ site: { id: siteId }, locale: { id: localeId } });
}

describe('useCountryConfig', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  test('returns AU config for ZimmermannAU + en', () => {
    mockSite('ZimmermannAU', 'en');
    const { result } = renderHook(() => useCountryConfig());
    expect(result.current).toBe(COUNTRIES.au);
    expect(result.current.checkoutOwner).toBe('sfcc');
    expect(result.current.globalEPricing).toBe(false);
  });

  test('returns UK config for ZimmermannUK + en-GB (not en-eu)', () => {
    mockSite('ZimmermannUK', 'en-GB');
    const { result } = renderHook(() => useCountryConfig());
    expect(result.current).toBe(COUNTRIES.uk);
    expect(result.current.sfccSiteId).toBe('ZimmermannUK');
  });

  test('returns en-eu config for ZimmermannEU + en-GB (not uk)', () => {
    mockSite('ZimmermannEU', 'en-GB');
    const { result } = renderHook(() => useCountryConfig());
    expect(result.current).toBe(COUNTRIES['en-eu']);
    expect(result.current.sfccSiteId).toBe('ZimmermannEU');
  });

  test('returns fr-eu config for ZimmermannEU + fr', () => {
    mockSite('ZimmermannEU', 'fr');
    const { result } = renderHook(() => useCountryConfig());
    expect(result.current).toBe(COUNTRIES['fr-eu']);
  });

  test('returns it-eu config for ZimmermannEU + it', () => {
    mockSite('ZimmermannEU', 'it');
    const { result } = renderHook(() => useCountryConfig());
    expect(result.current).toBe(COUNTRIES['it-eu']);
  });

  test('returns es-eu config for ZimmermannEU + es', () => {
    mockSite('ZimmermannEU', 'es');
    const { result } = renderHook(() => useCountryConfig());
    expect(result.current).toBe(COUNTRIES['es-eu']);
  });

  test('returns HK config with globalEPricing true for ZimmermannHK + en-HK', () => {
    mockSite('ZimmermannHK', 'en-HK');
    const { result } = renderHook(() => useCountryConfig());
    expect(result.current).toBe(COUNTRIES.hk);
    expect(result.current.checkoutOwner).toBe('global-e');
    expect(result.current.globalEPricing).toBe(true);
  });

  test('returns ME config for ZimmermannME + en-AE', () => {
    mockSite('ZimmermannME', 'en-AE');
    const { result } = renderHook(() => useCountryConfig());
    expect(result.current).toBe(COUNTRIES['en-ae']);
    expect(result.current.checkoutOwner).toBe('global-e');
  });

  test('falls back to AU default for unrecognised site ID', () => {
    mockSite('RefArch', 'en-US');
    const { result } = renderHook(() => useCountryConfig());
    expect(result.current).toBe(COUNTRIES.au);
  });

  test('falls back to AU default when both args are undefined', () => {
    mockUseMultiSite.mockReturnValue({ site: undefined, locale: undefined });
    const { result } = renderHook(() => useCountryConfig());
    expect(result.current).toBe(COUNTRIES.au);
  });
});

import React, {useMemo} from 'react'
import type {ContentfulClientApi} from 'contentful'
import Seo from '@salesforce/retail-react-app/app/components/seo'
import {useLocation} from 'react-router-dom'
import {Box, Spinner, Text} from '@salesforce/retail-react-app/app/components/shared/ui'
import {createClient} from 'contentful'
import {ExperienceRoot, useFetchBySlug} from '@contentful/experiences-sdk-react'
import {ContentfulLivePreviewProvider} from '@contentful/live-preview/react'
import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site'
import {
    getContentfulConfig,
    CONTENTFUL_FALLBACK_LOCALE,
    CONTENTFUL_PREVIEW_HOST,
    CONTENTFUL_DELIVERY_HOST,
    CONTENTFUL_LIVE_PREVIEW_ORIGIN,
} from '../../config/contentful'

// Side-effect import — registers experience components with the Contentful Experiences SDK (cached, so this is fine)
import '../../components/contentful/experiences/definitions'

const EXPERIENCE_TYPE_ID = 'collectionPageExp'

type ExperienceFetchProps = {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    client: ContentfulClientApi<any>
    slug: string
    locale: string
    isPreview: boolean
}

/** Inner component so useFetchBySlug is always called unconditionally at the top level. */
const ExperienceFetch = ({client, slug, locale, isPreview}: ExperienceFetchProps) => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const {experience, isLoading, error} = useFetchBySlug({
        client: client as any,
        slug,
        experienceTypeId: EXPERIENCE_TYPE_ID,
        localeCode: locale,
    })

    if (isLoading) {
        return (
            <Box p={8} display="flex" justifyContent="center">
                <Spinner size="xl" />
            </Box>
        )
    }

    if (error || !experience) {
        return (
            <Box p={8}>
                <Text color="red.500">Page not found.</Text>
            </Box>
        )
    }

    const root = <ExperienceRoot experience={experience} locale={locale} />

    if (isPreview) {
        return (
            <>
                {/* noindex — preview mode serves draft content, must not be indexed */}
                <Seo noIndex />
                <ContentfulLivePreviewProvider
                    locale={locale}
                    enableInspectorMode={true}
                    enableLiveUpdates={true}
                    targetOrigin={CONTENTFUL_LIVE_PREVIEW_ORIGIN}
                >
                    {root}
                </ContentfulLivePreviewProvider>
            </>
        )
    }

    return root
}

type ExperiencePageProps = {
    slug: string
    isPreview?: boolean
}

const ExperiencePage = ({slug, isPreview = false}: ExperiencePageProps) => {
    const {locale: siteLocale} = useMultiSite() as {locale?: {id: string}}
    const locale = siteLocale?.id || CONTENTFUL_FALLBACK_LOCALE
    const {spaceId, environment, previewAccessToken, accessToken} = getContentfulConfig() ?? {}
    const previewUnavailable = isPreview && !previewAccessToken
    // Use preview host only when explicitly in preview mode AND a preview token is available.
    // Falls back to delivery mode silently when no token is set (non-prod gate).
    const effectivePreview = isPreview && !!previewAccessToken
    const token = effectivePreview ? previewAccessToken : accessToken
    const host = effectivePreview ? CONTENTFUL_PREVIEW_HOST : CONTENTFUL_DELIVERY_HOST

    const client = useMemo(() => {
        if (!spaceId || !token) return null
        return createClient({space: spaceId, environment, accessToken: token, host})
    }, [spaceId, environment, token, host])

    if (previewUnavailable) {
        return (
            <Box p={8}>
                <Text color="red.500">
                    Preview is not enabled in this environment.
                </Text>
            </Box>
        )
    }

    if (!client) {
        return (
            <Box p={8}>
                <Text color="red.500">Contentful configuration is missing — cannot render this page.</Text>
            </Box>
        )
    }

    return <ExperienceFetch client={client} slug={slug} locale={locale} isPreview={effectivePreview} />
}

const Experience = () => {
    const {pathname, search} = useLocation()
    const slug = pathname.slice(1) // strip leading '/'
    const isPreview = new URLSearchParams(search).has('preview')

    return <ExperiencePage slug={slug} isPreview={isPreview} />
}

Experience.getTemplateName = () => 'experience';

export default Experience;

import React, {useEffect, useMemo, useState} from 'react'
import {useLocation} from 'react-router-dom'
import {Box, Spinner, Text} from '@salesforce/retail-react-app/app/components/shared/ui'
import {createClient} from 'contentful'
import type {ContentfulClientApi} from 'contentful'
import {ExperienceRoot, useFetchById} from '@contentful/experiences-sdk-react'
import {ContentfulLivePreviewProvider} from '@contentful/live-preview/react'
import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site'
import Seo from '@salesforce/retail-react-app/app/components/seo'
import {useServerContext} from '@salesforce/pwa-kit-react-sdk/ssr/universal/hooks'
import {
    getContentfulConfig,
    CONTENTFUL_FALLBACK_LOCALE,
    CONTENTFUL_PREVIEW_HOST,
    CONTENTFUL_DELIVERY_HOST,
    CONTENTFUL_LIVE_PREVIEW_ORIGIN,
} from '../../config/contentful'

// Side-effect import — registers experience components with the Contentful Experiences SDK
import '../../components/contentful/experiences/definitions'

type ExperienceViewProps = {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    client: ContentfulClientApi<any>
    entryId: string
    experienceTypeId: string
    locale: string
}

/** Fetches and renders the experience once we know its content type ID. */
const ExperienceView = ({client, entryId, experienceTypeId, locale}: ExperienceViewProps) => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const {experience, isLoading, error} = useFetchById({
        client: client as any,
        id: entryId,
        experienceTypeId,
        localeCode: locale,
    })

    if (isLoading) {
        return (
            <Box p={8} display="flex" justifyContent="center">
                <Spinner size="xl" />
            </Box>
        )
    }

    if (error) {
        return (
            <Box p={8}>
                <Text color="red.500">Failed to load preview: {error.message}</Text>
            </Box>
        )
    }

    if (!experience) {
        return (
            <Box p={8}>
                <Text color="orange.500">
                    Entry found (type: <strong>{experienceTypeId}</strong>) but it could not be
                    rendered as a Contentful Experience. Make sure the content type is configured as
                    an Experience Type in your Contentful space and that the entry is valid.
                </Text>
            </Box>
        )
    }

    return <ExperienceRoot experience={experience} locale={locale} />
}

type ContentfulPreviewPageProps = {
    entryId: string
    locale: string
}

/**
 * Resolves the entry's content type first (without a type filter), then delegates
 * to ExperienceView with the correct experienceTypeId so useFetchById can query
 * successfully regardless of which Experience content type the entry belongs to.
 */
const ContentfulPreviewPage = ({entryId, locale}: ContentfulPreviewPageProps) => {
    const {spaceId, environment, previewAccessToken, accessToken} = getContentfulConfig() ?? {}
    const token = previewAccessToken || accessToken

    const client = useMemo(() => {
        if (!spaceId || !token) return null
        return createClient({
            space: spaceId,
            environment,
            accessToken: token,
            host: previewAccessToken ? CONTENTFUL_PREVIEW_HOST : CONTENTFUL_DELIVERY_HOST,
        })
    }, [spaceId, environment, previewAccessToken, token])

    const [experienceTypeId, setExperienceTypeId] = useState<string | null>(null)
    const [typeError, setTypeError] = useState<string | null>(null)

    useEffect(() => {
        if (!client || !entryId) return
        let active = true
        setExperienceTypeId(null)
        setTypeError(null)
        client
            .getEntry(entryId)
            .then((entry) => {
                if (!active) return
                setExperienceTypeId(entry.sys.contentType.sys.id)
            })
            .catch((err: unknown) => {
                if (!active) return
                const msg = err instanceof Error ? err.message : String(err)
                setTypeError(`Could not load entry: ${msg}`)
            })
        return () => {
            active = false
        }
    }, [client, entryId, locale])

    if (!client) {
        return (
            <Box p={8}>
                <Text color="red.500">Contentful configuration is missing.</Text>
            </Box>
        )
    }

    if (typeError) {
        return (
            <Box p={8}>
                <Text color="red.500">{typeError}</Text>
            </Box>
        )
    }

    if (!experienceTypeId) {
        return (
            <Box p={8} display="flex" justifyContent="center">
                <Spinner size="xl" />
            </Box>
        )
    }

    return (
        <ExperienceView
            client={client}
            entryId={entryId}
            experienceTypeId={experienceTypeId}
            locale={locale}
        />
    )
}

const ContentfulPreview = () => {
    const {search} = useLocation()
    const params = new URLSearchParams(search)
    const entryId = params.get('entry') ?? ''

    // Locale priority: ?locale= query param (Contentful injects {locale} in preview URLs)
    // → active site locale from useMultiSite → fallback
    const {locale: siteLocale} = useMultiSite() as {locale?: {id: string}}
    const locale = params.get('locale') || siteLocale?.id || CONTENTFUL_FALLBACK_LOCALE

    const {previewAccessToken} = getContentfulConfig() ?? {}
    const {res} = useServerContext()

    // Gate: if no preview token is configured this is not a preview-enabled environment.
    // Return 404 so the route is inert on staging/prod even if accidentally visited.
    if (!previewAccessToken) {
        if (res) {
            res.status(404)
        }
        return (
            <>
                <Seo noIndex />
                <Box p={8}>
                    <Text color="red.500">Not found.</Text>
                </Box>
            </>
        )
    }

    if (!entryId) {
        return (
            <Box p={8}>
                <Text color="red.500">Missing &quot;entry&quot; query parameter.</Text>
            </Box>
        )
    }

    return (
        <>
            {/* noindex — this route is for Contentful editors only, not public */}
            <Seo noIndex />
            <ContentfulLivePreviewProvider
                locale={locale}
                enableInspectorMode={true}
                enableLiveUpdates={true}
                targetOrigin={CONTENTFUL_LIVE_PREVIEW_ORIGIN}
            >
                <ContentfulPreviewPage entryId={entryId} locale={locale} />
            </ContentfulLivePreviewProvider>
        </>
    )
}

ContentfulPreview.getTemplateName = () => 'contentful-preview'

export default ContentfulPreview

