import { describe, test, expect, vi, beforeEach } from 'vitest';
import { renderHook } from '@testing-library/react';
import { createClient } from 'contentful';
import {
  getContentfulConfig,
  CONTENTFUL_PREVIEW_HOST,
  CONTENTFUL_DELIVERY_HOST,
} from '../config/contentful';
import { useContentfulClient } from './useContentfulClient';

// Mock the SDK client factory so no real Contentful connection is attempted.
vi.mock('contentful', () => ({
  createClient: vi.fn(() => ({ mockClient: true })),
}));

// Mock only getContentfulConfig; keep the real host/locale constants via importOriginal.
vi.mock('../config/contentful', async (importOriginal) => {
  const actual = await importOriginal<typeof import('../config/contentful')>();
  return { ...actual, getContentfulConfig: vi.fn() };
});

const mockGetConfig = vi.mocked(getContentfulConfig);
const mockCreateClient = vi.mocked(createClient);

const FULL_CONFIG = {
  spaceId: 'space-123',
  environment: 'master',
  accessToken: 'cda-token',
  previewAccessToken: 'cpa-token',
};

describe('useContentfulClient', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  test('uses the preview host + CPA token when preview is requested and a token exists', () => {
    mockGetConfig.mockReturnValue(FULL_CONFIG);
    const { result } = renderHook(() => useContentfulClient({ preview: true }));

    expect(result.current.isPreview).toBe(true);
    expect(result.current.previewUnavailable).toBe(false);
    expect(result.current.client).not.toBeNull();
    expect(mockCreateClient).toHaveBeenCalledWith(
      expect.objectContaining({ accessToken: 'cpa-token', host: CONTENTFUL_PREVIEW_HOST }),
    );
  });

  test('flags previewUnavailable and does not enter preview mode when the CPA token is absent', () => {
    mockGetConfig.mockReturnValue({ ...FULL_CONFIG, previewAccessToken: '' });
    const { result } = renderHook(() => useContentfulClient({ preview: true }));

    // The caller is expected to 404 + noindex on this flag — never a silent delivery fallback.
    expect(result.current.previewUnavailable).toBe(true);
    expect(result.current.isPreview).toBe(false);
  });

  test('uses the delivery host + CDA token when preview is not requested', () => {
    mockGetConfig.mockReturnValue(FULL_CONFIG);
    const { result } = renderHook(() => useContentfulClient());

    expect(result.current.isPreview).toBe(false);
    expect(result.current.previewUnavailable).toBe(false);
    expect(mockCreateClient).toHaveBeenCalledWith(
      expect.objectContaining({ accessToken: 'cda-token', host: CONTENTFUL_DELIVERY_HOST }),
    );
  });

  test('returns a null client when required config is missing', () => {
    mockGetConfig.mockReturnValue({ ...FULL_CONFIG, spaceId: '' });
    const { result } = renderHook(() => useContentfulClient({ preview: true }));

    expect(result.current.client).toBeNull();
    expect(mockCreateClient).not.toHaveBeenCalled();
  });

  test('handles a missing Contentful config object without throwing', () => {
    // getContentfulConfig can return undefined if app.contentful is absent.
    mockGetConfig.mockReturnValue(undefined as never);
    const { result } = renderHook(() => useContentfulClient({ preview: true }));

    expect(result.current.client).toBeNull();
    expect(result.current.previewUnavailable).toBe(true);
  });
});

