import { useCallback } from 'react';
import { useFetchByBase } from './useFetchByBase.js';
import { fetchBySlug } from '@contentful/experiences-core';
import { useDetectCanvasMode } from './useDetectCanvasMode.js';

const useFetchBySlug = ({ slug, localeCode, client, experienceTypeId, hyperlinkPattern, }) => {
    const mode = useDetectCanvasMode({ isClientSide: typeof window !== 'undefined' });
    const fetchMethod = useCallback(() => {
        return fetchBySlug({ slug, localeCode, client, experienceTypeId });
        // we purposely don't want to include the client in the dependencies as it can cause infinite loops if the
        // user creates the client in the component
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [slug, localeCode, experienceTypeId]);
    const fetchResult = useFetchByBase(fetchMethod, mode);
    if (!fetchResult.experience) {
        return fetchResult;
    }
    // enriches fetchResult.experience with the hyperlinkPattern, only when fetchResult.experience exists
    return {
        ...fetchResult,
        experience: {
            ...fetchResult.experience,
            hyperlinkPattern,
        },
    };
};

export { useFetchBySlug };
//# sourceMappingURL=useFetchBySlug.js.map

